nvmem: core: fix use-after-free bugs in error paths

Fix several instances of error paths in which we call
__nvmem_device_put() - which may end up freeing the underlying memory
and other resources - and then keep on using the nvmem structure. Always
put the reference to the nvmem device as the last step before returning
the error code.

Cc: stable@vger.kernel.org
Fixes: 7ae6478b304b ("nvmem: core: rework nvmem cell instance creation")
Fixes: e888d445ac33 ("nvmem: resolve cells from DT at registration time")
Signed-off-by: Bartosz Golaszewski <bartosz.golaszewski@oss.qualcomm.com>
Signed-off-by: Srinivas Kandagatla <srini@kernel.org>
Link: https://patch.msgid.link/20260530204340.116743-3-srini@kernel.org
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
In the nvmem core error paths, __nvmem_device_put() was called before other operations that still access the nvmem structure, causing use-after-free bugs. The proper order is to first perform all operations that need the nvmem pointer (like nvmem_layout_module_put and reading nvmem->layout), and only then call __nvmem_device_put() to release the reference.

Here is the patch:
  */
 struct nvmem_cell *of_nvmem_cell_get(struct device_node *np, const char *id)
 {
 	struct device_node *cell_np, *nvmem_np;
 	struct nvmem_device *nvmem;
 	struct nvmem_cell_entry *cell_entry;
 	struct nvmem_cell *cell;
 	struct of_phandle_args cell_spec;
 	int index = 0;
 	int cell_index = 0;
 	int ret;

 	/* if cell name exists, find index to the name */
 	if (id)
 		index = of_property_match_string(np, "nvmem-cell-names", id);

 	ret = of_parse_phandle_with_optional_args(np, "nvmem-cells",
 						  "#nvmem-cell-cells",
 						  index, &cell_spec);
 	if (ret)
 		return ERR_PTR(-ENOENT);

 	if (cell_spec.args_count > 1)
 		return ERR_PTR(-EINVAL);

 	cell_np = cell_spec.np;
 	if (cell_spec.args_count)
 		cell_index = cell_spec.args[0];

 	nvmem_np = of_get_parent(cell_np);
 	if (!nvmem_np) {
 		of_node_put(cell_np);
 		return ERR_PTR(-EINVAL);
 	}

 	/* nvmem layouts produce cells within the nvmem-layout container */
 	if (of_node_name_eq(nvmem_np, "nvmem-layout")) {
 		nvmem_np = of_get_next_parent(nvmem_np);
 		if (!nvmem_np) {
 			of_node_put(cell_np);
 			return ERR_PTR(-EINVAL);
 		}
 	}

 	nvmem = __nvmem_device_get(nvmem_np, device_match_of_node);
 	of_node_put(nvmem_np);
 	if (IS_ERR(nvmem)) {
 		of_node_put(cell_np);
 		return ERR_CAST(nvmem);
 	}

 	ret = nvmem_layout_module_get_optional(nvmem);
 	if (ret) {
 		of_node_put(cell_np);
 		__nvmem_device_put(nvmem);
 		return ERR_PTR(ret);
 	}

 	cell_entry = nvmem_find_cell_entry_by_node(nvmem, cell_np);
 	of_node_put(cell_np);
 	if (!cell_entry) {
-		__nvmem_device_put(nvmem);
 		nvmem_layout_module_put(nvmem);
-		if (nvmem->layout)
-			return ERR_PTR(-EPROBE_DEFER);
-		else
-			return ERR_PTR(-ENOENT);
+		ret = nvmem->layout ? -EPROBE_DEFER : -ENOENT;
+		__nvmem_device_put(nvmem);
+		return ERR_PTR(ret);
 	}

 	cell = nvmem_create_cell(cell_entry, id, cell_index);
 	if (IS_ERR(cell)) {
-		__nvmem_device_put(nvmem);
 		nvmem_layout_module_put(nvmem);
+		__nvmem_device_put(nvmem);
 	}

 	return cell;
 }
 EXPORT_SYMBOL_GPL(of_nvmem_cell_get);
  */
 void nvmem_cell_put(struct nvmem_cell *cell)
 {
 	struct nvmem_device *nvmem = cell->entry->nvmem;

 	if (cell->id)
 		kfree_const(cell->id);

 	kfree(cell);
-	__nvmem_device_put(nvmem);
 	nvmem_layout_module_put(nvmem);
+	__nvmem_device_put(nvmem);
 }
 EXPORT_SYMBOL_GPL(nvmem_cell_put);


